bridge_code = '''"""DMGHG Local Bridge Service (Pure Python Standard Library).

Bridges HikerView PC runtime to the installed DMGHG Windows native C ABI service.
Only listens on 127.0.0.1 with permitted ports (18000, 18001, 18002).
"""
import argparse
import ctypes
import json
import os
from pathlib import Path
import re
import socket
import socketserver
import sys
import tempfile
import threading
import time
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import parse_qs, urlparse


class Bridge:
    READ_COMMANDS = {
        "app.ping", "catalog.get_channels", "catalog.get_banners",
        "catalog.get_video_list", "catalog.search_video", "catalog.get_video_key",
        "catalog.get_video_detail", "catalog.get_channel_detail", "video.play",
    }

    def __init__(self, app_dir):
        if os.name != "nt":
            raise RuntimeError("The installed bridge requires Windows x64 Python")
        self.app_dir = Path(app_dir).resolve(strict=True)
        self.dll_path = self.app_dir / "electron_bridge.dll"
        if not self.dll_path.is_file():
            raise RuntimeError("electron_bridge.dll is missing from the selected application")
        self.state_root = Path(tempfile.mkdtemp(prefix="dmghg-headless-"))
        os.environ["DMGHG_TEST_DATA_ROOT"] = str(self.state_root)
        os.environ["RUST_LOG"] = "error"
        self.dll = ctypes.CDLL(str(self.dll_path))
        self.dll.dmghg_service_new.argtypes = [ctypes.c_char_p, ctypes.c_char_p]
        self.dll.dmghg_service_new.restype = ctypes.c_void_p
        self.dll.dmghg_service_handle_command_json.argtypes = [ctypes.c_void_p, ctypes.c_char_p]
        self.dll.dmghg_service_handle_command_json.restype = ctypes.c_void_p
        self.dll.dmghg_string_free.argtypes = [ctypes.c_void_p]
        self.dll.dmghg_service_free.argtypes = [ctypes.c_void_p]
        self.lock = threading.RLock()
        self.version = installed_version(self.app_dir / "dmghg.exe")
        self.handle = self.dll.dmghg_service_new(b"dmghg-flutter", self.version.encode("ascii"))
        if not self.handle:
            raise RuntimeError("The installed bridge could not initialize")

    def call(self, command, payload=None):
        if command not in self.READ_COMMANDS:
            raise ValueError(f"Command '{command}' is outside the read allowlist")
        request = {
            "request_id": "headless-bridge",
            "protocol_version": 1,
            "command": command,
            "payload": payload or {}
        }
        with self.lock:
            previous = Path.cwd()
            try:
                # The installed Lua resolver loads resources/lua relative to Cwd.
                os.chdir(self.app_dir)
                ptr = self.dll.dmghg_service_handle_command_json(
                    self.handle, json.dumps(request, ensure_ascii=False).encode("utf-8")
                )
                if not ptr:
                    raise RuntimeError("Bridge returned a null response")
                try:
                    response = json.loads(ctypes.string_at(ptr).decode("utf-8"))
                finally:
                    self.dll.dmghg_string_free(ptr)
            finally:
                os.chdir(previous)
        if response.get("ok") is not True:
            error = response.get("error", {})
            raise RuntimeError(f"{error.get('code')}: {error.get('message')}")
        return response.get("data")

    def close(self):
        with self.lock:
            if self.handle:
                self.dll.dmghg_service_free(self.handle)
                self.handle = None


def installed_version(exe):
    """Read PE version metadata; the resolver rejects unsupported client versions."""
    version = ctypes.windll.version
    size = version.GetFileVersionInfoSizeW(str(exe), None)
    if not size:
        raise RuntimeError("Cannot read the installed application's version metadata")
    buffer = ctypes.create_string_buffer(size)
    if not version.GetFileVersionInfoW(str(exe), 0, size, buffer):
        raise RuntimeError("Cannot read application version info")
    info = ctypes.c_void_p()
    length = ctypes.c_uint()
    if not version.VerQueryValueW(buffer, "\\\\", ctypes.byref(info), ctypes.byref(length)):
        raise RuntimeError("Application version structure is missing")
    fields = ctypes.cast(info, ctypes.POINTER(ctypes.c_uint32))
    if fields[0] != 0xFEEF04BD or length.value < 52:
        raise RuntimeError("Application version structure is invalid")
    return f"{fields[2] >> 16}.{fields[2] & 65535}.{fields[3] >> 16}"


class ThreadingHTTPServer(socketserver.ThreadingMixIn, HTTPServer):
    daemon_threads = True
    allow_reuse_address = True


class BridgeHandler(BaseHTTPRequestHandler):
    timeout = 5.0
    protocol_version = "HTTP/1.1"

    def setup(self):
        super().setup()
        if self.connection:
            self.connection.settimeout(5.0)

    def send_json(self, status, data):
        body = json.dumps(data, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Connection", "close")
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path
        qs = parse_qs(parsed.query)

        bridge = self.server.bridge

        if path in ("/ping", "/api/ping"):
            self.send_json(200, {"ok": True, "version": bridge.version, "service": "dmghg-bridge"})
            return

        if path in ("/channels", "/api/channels"):
            try:
                channels = bridge.call("catalog.get_channels")
                self.send_json(200, {"ok": True, "data": channels})
            except Exception as e:
                self.send_json(500, {"ok": False, "error": {"code": "BRIDGE_ERROR", "message": str(e)}})
            return

        if path == "/api/list":
            try:
                channel = qs.get("channel", ["20"])[0]
                page = qs.get("page", ["1"])[0]
                payload = {
                    "channel": int(channel) if channel.isdigit() else channel,
                    "page": int(page) if page.isdigit() else 1
                }
                res = bridge.call("catalog.get_video_list", payload)
                self.send_json(200, {"ok": True, "data": res})
            except Exception as e:
                self.send_json(500, {"ok": False, "error": {"code": "BRIDGE_ERROR", "message": str(e)}})
            return

        if path == "/api/search":
            try:
                key = qs.get("key", [""])[0]
                page = qs.get("page", ["1"])[0]
                payload = {"key": key, "page": str(page)}
                res = bridge.call("catalog.search_video", payload)
                self.send_json(200, {"ok": True, "data": res})
            except Exception as e:
                self.send_json(500, {"ok": False, "error": {"code": "BRIDGE_ERROR", "message": str(e)}})
            return

        if path == "/api/detail":
            try:
                vid = qs.get("id", [""])[0]
                payload = {"id": str(vid)}
                res = bridge.call("catalog.get_video_detail", payload)
                self.send_json(200, {"ok": True, "data": res})
            except Exception as e:
                self.send_json(500, {"ok": False, "error": {"code": "BRIDGE_ERROR", "message": str(e)}})
            return

        if path == "/api/play":
            try:
                vid = qs.get("id", [""])[0]
                play_line = qs.get("play", [""])[0]
                part_name = qs.get("part", [""])[0]
                payload = {"id": str(vid), "play": play_line, "part": part_name, "resolve": True}
                res = bridge.call("video.play", payload)
                variant = res["list"][res["default"]]
                # Keep real headers as returned by native video.play; do not inject extra Referer or User-Agent
                headers = variant.get("headers") or {}
                self.send_json(200, {
                    "ok": True,
                    "data": {
                        "url": variant["url"],
                        "headers": headers,
                        "name": variant.get("name", ""),
                        "resolution": variant.get("resolution", "")
                    }
                })
            except Exception as e:
                self.send_json(500, {"ok": False, "error": {"code": "BRIDGE_ERROR", "message": str(e)}})
            return

        self.send_json(404, {"ok": False, "error": {"code": "NOT_FOUND", "message": f"Route '{path}' not found"}})

    def do_POST(self):
        parsed = urlparse(self.path)
        path = parsed.path

        if path not in ("/call", "/api/call"):
            self.send_json(404, {"ok": False, "error": {"code": "NOT_FOUND", "message": f"Route '{path}' not found"}})
            return

        content_length_str = self.headers.get("Content-Length", "")
        if not content_length_str or not content_length_str.isdigit():
            self.send_json(400, {"ok": False, "error": {"code": "BAD_REQUEST", "message": "Missing Content-Length"}})
            return

        content_length = int(content_length_str)
        if content_length > 1024 * 1024:
            self.send_json(413, {"ok": False, "error": {"code": "PAYLOAD_TOO_LARGE", "message": "Payload exceeds 1MB"}})
            return

        try:
            body = self.rfile.read(content_length)
            req_data = json.loads(body.decode("utf-8"))
        except Exception as e:
            self.send_json(400, {"ok": False, "error": {"code": "BAD_JSON", "message": f"Invalid JSON payload: {str(e)}"}})
            return

        command = req_data.get("command")
        payload = req_data.get("payload", {})

        if not isinstance(command, str) or not command:
            self.send_json(400, {"ok": False, "error": {"code": "INVALID_COMMAND", "message": "Field 'command' must be non-empty string"}})
            return

        if command not in Bridge.READ_COMMANDS:
            self.send_json(403, {"ok": False, "error": {"code": "FORBIDDEN_COMMAND", "message": f"Command '{command}' is not in the read-only whitelist"}})
            return

        bridge = self.server.bridge
        try:
            result = bridge.call(command, payload)
            self.send_json(200, {"ok": True, "data": result})
        except Exception as e:
            self.send_json(500, {"ok": False, "error": {"code": "BRIDGE_ERROR", "message": str(e)}})


def run_server(app_dir, port=18002):
    bridge = Bridge(app_dir)
    server_address = ("127.0.0.1", port)
    httpd = ThreadingHTTPServer(server_address, BridgeHandler)
    httpd.bridge = bridge
    try:
        print(f"DMGHG Bridge listening on [REDACTED_URL] (app_dir={app_dir})")
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
        bridge.close()


def main():
    parser = argparse.ArgumentParser(description="DMGHG Local Native Bridge Service")
    parser.add_argument("--app-dir", required=True, help="Installed DMGHG application directory")
    parser.add_argument("--port", type=int, default=18002, help="Port to bind (must be one of 18000, 18001, 18002)")
    parser.add_argument("--host", default="127.0.0.1", help="Host address (strictly 127.0.0.1 only)")
    args = parser.parse_args()

    if args.host != "127.0.0.1":
        print(f"Error: Host '{args.host}' is not permitted. Strictly 127.0.0.1 only.", file=sys.stderr)
        sys.exit(1)

    if args.port not in (18000, 18001, 18002):
        print(f"Error: Port {args.port} is outside permitted ports (18000, 18001, 18002).", file=sys.stderr)
        sys.exit(1)

    run_server(args.app_dir, args.port)


if __name__ == "__main__":
    main()
